export const getDownloadDistrictExportUrl = (
  planId: string,
  exportId: string,
  params: DownloadDistrictExportParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/district-plans/${planId}/exports/${exportId}/file?${stringifiedParams}`
    : `/api/district-plans/${planId}/exports/${exportId}/file`;
};

